A driver for UEFI with support for:
- displays
- indevs (keyboard, mouse and touch)
- file access

Currently I only tested it on X64 systems without touch support.
The driver is still work in progress. I hope to get some feedback about the API before i finish the pull request.

Config options:
- LV_USE_UEFI: enable the driver
- LV_UEFI_HEADERS_EDK2: use the headers from the EDK2 project
- LV_UEFI_HEADERS_GNU_EFI: use the headers from the gnu-efi project
- LV_UEFI_HEADERS_CUSTOM: use custom headers
- LV_UEFI_CUSTOM_INCLUDE_PATH: include path for the custom header
- LV_UEFI_USE_MEMORY_SERVICES: use the memory services that are provided by the firmware (requires LV_USE_STDLIB_MALLOC == LV_STDLIB_CUSTOM)
- LV_USE_FS_UEFI: enable the file system driver
- LV_FS_UEFI_LETTER: drive letter for the driver

Simple test app:
```
// LV_USE_UEFI = 1
// Choose the correct header type and write a wrapper for the types (check tests/makefile_uefi/efi.h for the required types and defines)
// LV_UEFI_USE_MEMORY_SERVICES = 1
// LV_USE_FS_UEFI = 1
// LV_FS_UEFI_LETTER = 'E'
EFI_STATUS EFIAPI efi_main(EFI_HANDLE image_handle, EFI_SYSTEM_TABLE * system_table)
{
    EFI_HANDLE handle = NULL;
    lv_display_t* display = NULL;
    lv_indev_t* indev = NULL;
    lv_group_t* group = NULL;
    lv_obj_t* cursor = NULL;
    // used to get out of the main loop
    size_t counter;

    lv_uefi_init(image_handle, system_table);
    lv_init();
    if(!lv_is_initialized()) return EFI_NOT_READY;

    // Init the display
    handle = lv_uefi_display_get_active();
    if(handle == NULL) {
        handle = lv_uefi_display_get_any();
    }
    if(handle == NULL) {
        lv_deinit();
        return EFI_UNSUPPORTED;
    }

    display = lv_uefi_display_create(handle); 
    lv_display_set_default(display);

    // Create the group
    group = lv_group_create();
    lv_group_set_default(group);

    // Create an image that can be used as cursor
    cursor = lv_image_create(lv_layer_top());
    lv_image_set_src(cursor, "E:cursor.png");

    // Create the input devices
    indev = lv_uefi_simple_text_input_indev_create(); 
    lv_indev_set_group(indev, lv_group_get_default());
    lv_uefi_simple_text_input_indev_add_all(indev);

    indev = lv_uefi_simple_pointer_indev_create(NULL); 
    lv_uefi_simple_pointer_indev_add_all(indev);
    lv_indev_set_cursor(indev, cursor);

    indev = lv_uefi_absolute_pointer_indev_create(NULL);
    lv_uefi_absolute_pointer_indev_add_all(indev); 

    lv_demo_widgets();

    // Run main loop for ~ 10 seconds
    counter = 0;
    while(counter < 10000) {
        counter ++;
        gBS->Stall(1000);
        lv_tick_inc(1);
        lv_timer_handler();
    }

    lv_deinit();

    return EFI_SUCCESS;
}
```

